// app/Sources/GraphicCatalog.swift — what Insert ▸ Graphic… lists (spec §11
// G-45): the bundled templates and the project's own modules as categories
// of graphics, in the one order the sheet (`GraphicBrowserSheetController`)
// and `list_graphics` (`AgentServer+GraphicBrowser.swift`) both show.
//
// **A template is compiled to read its `meta`, once per process**
// (`GraphicTemplateLibrary`, G-45 (e)): its title is `meta.name`, its
// category `meta.category`, its description `meta.description`. The first
// read is on main, when the browser or the tool first asks; it compiles
// against a library of the bundled fonts alone and is memoised under a lock.
// The menu bar never reads it (chrome probes instantiate `AppDelegate()`).
//
// **A project module is read from the registry**: the document's compiled
// set, as the inspector and the op tools read it. A module that does not
// compile is still listed (`ok` false), titled from its stem, so a person
// can see it is there and read why it will not insert.

import Foundation

/// One graphic the browser lists.
struct GraphicBrowserItem: Equatable {
    enum Origin: String { case template, project }
    /// A template's file stem; a project module's name.
    let name: String
    /// `GraphicCatalog.title(meta:name:)`; a This Project duplicate carries
    /// " — <name>" (G-45 (e)).
    let title: String
    let description: String?
    /// The module's own category (`meta.category`, else "Other") — a This
    /// Project item keeps its own here though it is listed under This Project.
    let category: String
    let origin: Origin
    /// The module compiled.
    let ok: Bool
}

/// One category and its graphics, in order.
struct GraphicBrowserCategory: Equatable {
    let name: String
    let items: [GraphicBrowserItem]
}

enum GraphicCatalog {
    static let thisProject = "This Project", other = "Other"

    /// G-45 (a): `meta.category` trimmed when it is a non-empty string, else
    /// "Other".
    static func category(meta: [String: Any]) -> String {
        let named = (meta["category"] as? String)?
            .trimmingCharacters(in: .whitespacesAndNewlines) ?? ""
        return named.isEmpty ? other : named
    }

    /// G-45 (e): `meta.name` when it is a non-empty string, else the stem's
    /// title (`GraphicTemplates.title(for:)`).
    static func title(meta: [String: Any], name: String) -> String {
        let named = (meta["name"] as? String)?
            .trimmingCharacters(in: .whitespacesAndNewlines) ?? ""
        return named.isEmpty ? GraphicTemplates.title(for: name) : named
    }

    /// `meta.description` trimmed, nil when absent or blank.
    static func description(meta: [String: Any]) -> String? {
        let text = (meta["description"] as? String)?
            .trimmingCharacters(in: .whitespacesAndNewlines) ?? ""
        return text.isEmpty ? nil : text
    }

    /// One item from a compiled (or failed, or absent) registry entry.
    static func item(
        name: String, entry: GraphicRegistry.Entry?, origin: GraphicBrowserItem.Origin
    ) -> GraphicBrowserItem {
        var meta: [String: Any] = [:]
        var ok = false
        if case .compiled(_, _, let described, _)? = entry {
            meta = described
            ok = true
        }
        return GraphicBrowserItem(
            name: name, title: title(meta: meta, name: name), description: description(meta: meta),
            category: category(meta: meta), origin: origin, ok: ok)
    }

    /// G-45 (d): This Project first, only when `project` holds an item, with
    /// (e)'s duplicate titles told apart; then the templates' categories by
    /// case-insensitive name, Other last. Items by title case-insensitively,
    /// then by name.
    static func categories(
        templates: [GraphicBrowserItem], project: [GraphicBrowserItem]
    ) -> [GraphicBrowserCategory] {
        let ours: [GraphicBrowserCategory] = project.isEmpty ? []
            : [GraphicBrowserCategory(name: thisProject, items: sorted(distinguished(project)))]
        let names = Set(templates.map(\.category)).sorted { a, b in
            if (a == other) != (b == other) { return b == other }
            return a.caseInsensitiveCompare(b) == .orderedAscending
        }
        let theirs = names.map { name in
            GraphicBrowserCategory(
                name: name, items: sorted(templates.filter { $0.category == name }))
        }
        return ours + theirs
    }

    /// The document's list: the bundled templates and the modules its
    /// `graphics/` holds as the registry compiled them. Main.
    static func categories(for document: ProjectDocument) -> [GraphicBrowserCategory] {
        let templates = GraphicTemplateLibrary.shared.entries.map {
            item(name: $0.template.name, entry: $0.entry, origin: .template)
        }
        let modules = document.graphicStore?.scan.modules.keys.sorted() ?? []
        let project = modules.map {
            item(
                name: $0, entry: GraphicRegistry.shared.entry(named: $0, for: document.recipeKey),
                origin: .project)
        }
        return categories(templates: templates, project: project)
    }

    /// By title, case-insensitively, then by name.
    private static func sorted(_ items: [GraphicBrowserItem]) -> [GraphicBrowserItem] {
        items.sorted { a, b in
            switch a.title.caseInsensitiveCompare(b.title) {
            case .orderedAscending: return true
            case .orderedDescending: return false
            case .orderedSame: return a.name < b.name
            }
        }
    }

    /// Every item whose title another item shares, case-insensitively,
    /// titled "<title> — <name>".
    private static func distinguished(_ items: [GraphicBrowserItem]) -> [GraphicBrowserItem] {
        var counts: [String: Int] = [:]
        let key = { (title: String) in title.folding(options: .caseInsensitive, locale: nil) }
        for item in items { counts[key(item.title), default: 0] += 1 }
        return items.map { item in
            guard counts[key(item.title), default: 0] > 1 else { return item }
            return GraphicBrowserItem(
                name: item.name, title: "\(item.title) — \(item.name)",
                description: item.description, category: item.category, origin: item.origin,
                ok: item.ok)
        }
    }
}

/// The bundled templates, compiled once against a library of the bundled
/// fonts (G-45 (e)): what the browser reads their `meta` from and what its
/// preview draws them with.
final class GraphicTemplateLibrary {
    struct Entry {
        let template: GraphicTemplate
        let entry: GraphicRegistry.Entry
    }

    static let shared = GraphicTemplateLibrary(
        directory: GraphicTemplates.bundledDirectory, fonts: ProjectDocument.bundledFontsDirectory)

    private let directory: URL
    private let fonts: URL
    private let lock = NSLock()
    private var compiled: [Entry]?

    init(directory: URL, fonts: URL) {
        self.directory = directory
        self.fonts = fonts
    }

    /// Every template in `GraphicTemplates.list(in:)`'s order, compiled on
    /// the first read and kept. The first read is on main.
    var entries: [Entry] {
        lock.lock()
        defer { lock.unlock() }
        if let compiled = compiled { return compiled }
        let made = compile()
        compiled = made
        return made
    }

    func entry(named name: String) -> Entry? {
        entries.first { $0.template.name == name }
    }

    /// The bundled faces into a new library, then every template compiled
    /// against it. A face the engine refuses fails every template with its
    /// sentence, as `GraphicRegistry.install` does for a document.
    private func compile() -> [Entry] {
        let templates = GraphicTemplates.list(in: directory)
        let library = GraphicLibrary()
        var refused: [GraphicDiagnostic]?
        let faces = ((try? FileManager.default.contentsOfDirectory(
            at: fonts, includingPropertiesForKeys: nil)) ?? [])
            .filter { GraphicStore.fontExtensions.contains($0.pathExtension.lowercased()) }
            .sorted { $0.lastPathComponent < $1.lastPathComponent }
        do {
            for face in faces { try library.addFont(Data(contentsOf: face)) }
        } catch {
            refused = GraphicDiagnostic.of(error)
        }
        return templates.map { template in
            let bytes = (try? Data(contentsOf: template.url)) ?? Data()
            if let refused = refused {
                return Entry(template: template, entry: .failed(refused, revision: ""))
            }
            let file = GraphicModuleFile(
                name: template.name, url: template.url, bytes: bytes, revision: "")
            return Entry(template: template, entry: GraphicRegistry.compile(file, library: library))
        }
    }
}
import AppKit

/// The menu bar's graphics rows (road map 10's G5b; spec §11 G-45): the
/// Insert menu, and Help ▸ Graphics Reference's action; and File's three
/// graphic-file items (spec §11 G-30, issue batch B84). Insert holds
/// Adjustment Clip first (spec §11 GR-6), then Graphic…, which puts up the
/// graphic browser (`GraphicBrowserSheetController.swift`), whose From
/// File… button replaced the old submenu's item, then Text Behind Subject,
/// last (spec §11 CO-53). All are nil-target selectors the editor implements
/// and validates (`EditorViewController+Adjustment.swift`,
/// `EditorViewController+GraphicMenus.swift`,
/// `EditorViewController+BehindSubject.swift`), with no key equivalent:
/// every bare letter belongs to the editor's own `keyDown` (spec §9).
///
/// **The menu bar compiles nothing and lists no template**: chrome probes
/// build it by instantiating `AppDelegate()`, and the browser compiles the
/// templates (`GraphicTemplateLibrary`) only when it is opened.
///
/// `showGraphicsReference` lives on the delegate, like `showSettings`, so it
/// resolves with no document open; `AppDelegate.validateMenuItem` enables it
/// while the bundled `GraphicsAPI.md` is there.
extension AppDelegate {

    /// "Insert", holding Adjustment Clip, then Graphic…, then Text Behind
    /// Subject.
    func insertMenu() -> NSMenu {
        let menu = NSMenu(title: "Insert")
        menu.addItem(
            item("Adjustment Clip", #selector(EditorViewController.insertAdjustmentClip(_:))))
        menu.addItem(item("Graphic…", #selector(EditorViewController.showGraphicBrowser(_:))))
        menu.addItem(
            item(
                "Text Behind Subject",
                #selector(EditorViewController.insertTextBehindSubject(_:))))
        return menu
    }

    /// File's graphic-file group (spec §11 G-30 (a)): a separator, then
    /// Rename Graphic…, Delete Graphic… and Restore Graphic Version…, each a
    /// nil-target selector the editor implements and validates
    /// (`EditorViewController+GraphicFiles.swift`). No key equivalents, the
    /// caption items' reason.
    func addGraphicFileItems(to menu: NSMenu) {
        menu.addItem(.separator())
        menu.addItem(
            item(
                GraphicFileAct.rename.menuTitle, #selector(EditorViewController.renameGraphic(_:))))
        menu.addItem(
            item(
                GraphicFileAct.delete.menuTitle, #selector(EditorViewController.deleteGraphic(_:))))
        menu.addItem(
            item(
                GraphicFileAct.restore.menuTitle,
                #selector(EditorViewController.restoreGraphicVersion(_:))))
    }

    /// Help ▸ Graphics Reference: the bundled `GraphicsAPI.md` in the
    /// person's default app for Markdown — the file `graphic_reference`
    /// answers.
    @objc func showGraphicsReference(_ sender: Any?) {
        NSWorkspace.shared.open(GraphicStore.bundledReferenceURL)
    }
}
import AppKit
import UniformTypeIdentifiers

/// The graphics menu commands (road map 10's G5b; spec §11 G-45): Insert ▸
/// Graphic…, the sheet (`GraphicBrowserSheetController.swift`) and its From
/// File…, and File ▸ Add Font to Graphics… and Add Image to Graphics…. Each
/// is the same code its MCP tool runs.
///
/// **Insert is `write_graphic` then `add_graphic_clip`** (spec §7.9) for a
/// template or a chosen `.js`: the module is written into the package's
/// `graphics/` under a free name and the folder rescanned
/// (`ProjectDocument.writeGraphicModule`, G-16 (b)), and one clip is placed
/// by `addGeneratedClip`'s rule — the front track if it fits, else a new
/// track above everything, Add Text's rule (G-16 (a)) — at the module's
/// `meta` duration and size (`ProjectDocument.graphicClipMaker`). A This
/// Project graphic is the clip alone, no copy (G-45 (f)). A module that does
/// not compile places nothing (G-16 (c)); the file write is not undoable
/// (G-3) and the clip is one undo step, "Insert Graphic". `insert_graphic`
/// calls the same two document bodies.
///
/// **From File… takes a `.fjgraphic` too** (spec §11 G-47 (a)): the package
/// goes to `GraphicImportSheetController.ask(packageAt:editor:)`, which asks
/// before copying it into this project's `graphics/`; a `.js` is inserted as
/// before.
///
/// The sheet's Insert runs INSIDE its button's event, so `applyEdit`; the
/// panels' completions are OFF-EVENT, so `performGroupedEdit` (app/CLAUDE.md's
/// undo pitfall). `rescan()` is called from the command, never from a
/// `.graphicsDidChange` observer.
extension EditorViewController {

    /// Insert ▸ Graphic…: the browser, as a sheet on the editor's window.
    @objc func showGraphicBrowser(_ sender: Any?) {
        guard let document = document, document.graphicStore != nil else {
            NSSound.beep()
            return
        }
        let sheet = GraphicBrowserSheetController(document: document, editor: self)
        presentAsSheet(sheet)
    }

    /// The browser after an import (spec §11 G-47 (f)): This Project's `name` chosen and
    /// `message` in its message line.
    func showGraphicBrowser(selecting name: String, message: String) {
        guard let document = document, document.graphicStore != nil else {
            NSSound.beep()
            return
        }
        presentAsSheet(GraphicBrowserSheetController(
            document: document, editor: self, select: name, message: message))
    }

    /// The sheet's From File…: a `.js` or a `.fjgraphic` chosen in a panel. Called from the
    /// browser's `viewDidDisappear`, once the browser is down, so the panel
    /// is the sheet that follows it.
    func insertGraphicFromFile(_ sender: Any?) {
        guard document?.graphicStore != nil, let window = view.window else {
            NSSound.beep()
            return
        }
        let panel = NSOpenPanel()
        panel.allowsMultipleSelection = false
        panel.canChooseDirectories = false
        panel.allowedContentTypes = [.javaScript, GraphicPackage.contentType]
        panel.message = "Choose a graphic module (.js) or a graphic package (.fjgraphic) to copy "
            + "into this project's graphics."
        panel.beginSheetModal(for: window) { [weak self] response in
            guard let self, response == .OK, let url = panel.url else { return }
            if url.pathExtension.lowercased() == GraphicPackage.fileExtension {
                GraphicImportSheetController.ask(packageAt: url, editor: self)
                return
            }
            self.reportingGraphicFailure { try self.insertGraphic(from: url, grouped: true) }
        }
    }

    /// File ▸ Add Font to Graphics… — `import_graphic_font`'s body.
    @objc func addGraphicFont(_ sender: Any?) {
        chooseGraphicFile(
            types: GraphicStore.fontExtensions,
            message: "Choose a font (.ttf or .otf) to add to this project's graphics."
        ) { store, url in
            _ = try store.importFont(from: url)
        }
    }

    /// File ▸ Add Image to Graphics… — `import_graphic_asset`'s body, filed
    /// under the picture's own name.
    @objc func addGraphicImage(_ sender: Any?) {
        chooseGraphicFile(
            types: GraphicStore.assetExtensions,
            message: "Choose a picture (\(GraphicStore.assetKinds)) to add to this project's "
                + "graphics."
        ) { [weak self] _, url in try self?.addGraphicImage(from: url) }
    }

    /// Add Image's body, no panel: the picture filed under its own name, or
    /// under a legal one with a sheet saying so (spec §11 G-23 (d)).
    func addGraphicImage(from url: URL) throws {
        guard let document = document, let store = document.graphicStore else {
            throw ReelCoreError(
                message: "This project has no graphics folder open (its window has not been made)")
        }
        let landed = try store.importAsset(from: url, as: url.lastPathComponent)
        if let asked = landed.renamedFrom, view.window != nil {
            showGraphicNotice(GraphicAssetName.renameNotice(from: asked, to: landed.name))
        }
    }

    /// The body, no dialog: write `url`'s module under a free name, rescan,
    /// and place a clip drawn by it — or throw the sentence saying why not.
    func insertGraphic(from url: URL, grouped: Bool) throws {
        guard let document = document else {
            throw ReelCoreError(message: ProjectDocument.noGraphicsFolderSentence)
        }
        let written = try document.writeGraphicModule(from: url)
        let make = try document.graphicClipMaker(named: written)
        addGeneratedClip(named: "Insert Graphic", grouped: grouped, make)
    }

    /// A This Project graphic placed: a clip drawn by `graphics/<name>.js`
    /// as it is, no copy written (spec §11 G-45 (f)) — or the sentence
    /// saying why not.
    func insertProjectGraphic(named name: String, grouped: Bool) throws {
        guard let document = document else {
            throw ReelCoreError(message: ProjectDocument.noGraphicsFolderSentence)
        }
        let make = try document.graphicClipMaker(named: name)
        addGeneratedClip(named: "Insert Graphic", grouped: grouped, make)
    }

    /// The menu arms for the three, answered from `validateUserInterfaceItem`'s
    /// default case: each needs the document's graphics store, which
    /// `startGraphicStore()` makes with the window. Any other action is
    /// forwarded to `validateGraphicFileAction`, the arm for File ▸ Rename
    /// Graphic…, Delete Graphic… and Restore Graphic Version…
    /// (`EditorViewController+GraphicFiles.swift`), which answers nil for
    /// an action that is none of the three.
    func validateGraphicMenuAction(_ action: Selector) -> Bool? {
        switch action {
        case #selector(showGraphicBrowser(_:)), #selector(addGraphicFont(_:)),
            #selector(addGraphicImage(_:)):
            return document?.graphicStore != nil
        default:
            return validateGraphicFileAction(action)
        }
    }

    // MARK: - Helpers

    /// A file panel over `types` (file extensions); its completion runs
    /// `body` with the store and the chosen URL, a failure in a sheet.
    private func chooseGraphicFile(
        types: Set<String>, message: String,
        _ body: @escaping (GraphicStore, URL) throws -> Void
    ) {
        guard let store = document?.graphicStore, let window = view.window else {
            NSSound.beep()
            return
        }
        let panel = NSOpenPanel()
        panel.allowsMultipleSelection = false
        panel.canChooseDirectories = false
        panel.allowedContentTypes = types.sorted().compactMap { UTType(filenameExtension: $0) }
        panel.message = message
        panel.beginSheetModal(for: window) { [weak self] response in
            guard response == .OK, let url = panel.url else { return }
            self?.reportingGraphicFailure { try body(store, url) }
        }
    }

    /// Runs `body`; a throw is shown in a sheet on the editor's window
    /// (`addImageBackground`'s shape), or a beep with no window. Success
    /// shows nothing.
    private func reportingGraphicFailure(_ body: () throws -> Void) {
        do {
            try body()
        } catch {
            guard let window = view.window else {
                NSSound.beep()
                return
            }
            NSAlert(error: error).beginSheetModal(for: window, completionHandler: nil)
        }
    }

    /// An informational sheet on the editor's window saying `text`.
    private func showGraphicNotice(_ text: String) {
        guard let window = view.window else { return }
        let alert = NSAlert()
        alert.alertStyle = .informational
        alert.messageText = text
        alert.beginSheetModal(for: window, completionHandler: nil)
    }
}
import AppKit

/// File ▸ Rename Graphic…, Delete Graphic… and Restore Graphic Version…
/// (spec §11 G-30; issue #103, issue batch B84): three menu actions, the
/// one place their sheet goes up, and their validator arm. The sheet,
/// `GraphicFileSheetController`, calls the bodies the three tools call
/// (`ProjectDocument+GraphicFiles.swift`); nothing here writes a file or
/// applies an op.
///
/// **Where a sheet opens** (G-30 (d)): Rename and Restore on the graphic of
/// the ONE selected clip when it is a row, else the first; Delete always on
/// the first. `selectedClips` is the open scope's selection.
///
/// **When an item is live** (G-30 (f)): something to list, and for Rename
/// no nest open. `validateGraphicMenuAction`'s default arm forwards here;
/// the frozen file's validator has already answered false with a sheet
/// attached. On every menu open Rename and Delete ask the last scan, and
/// Restore `keptNames()`: file names under `graphics/history/`, no bytes.
extension EditorViewController {

    /// File ▸ Rename Graphic… — `rename_graphic`'s body.
    @objc func renameGraphic(_ sender: Any?) {
        presentGraphicFileSheet(.rename)
    }

    /// File ▸ Delete Graphic… — `delete_graphic`'s body.
    @objc func deleteGraphic(_ sender: Any?) {
        presentGraphicFileSheet(.delete)
    }

    /// File ▸ Restore Graphic Version… — `restore_graphic`'s body, the
    /// newest kept text.
    @objc func restoreGraphicVersion(_ sender: Any?) {
        presentGraphicFileSheet(.restore)
    }

    /// The sheet for `act`, or a beep when the item has nothing to offer.
    func presentGraphicFileSheet(_ act: GraphicFileAct) {
        guard let document = document, GraphicFileSheetController.isOffered(act, in: document)
        else {
            NSSound.beep()
            return
        }
        let choices = GraphicFileSheetController.choices(for: act, in: document)
        let clips = selectedClips
        let selected = clips.count == 1 ? clips[0].graphic?.name : nil
        let sheet = GraphicFileSheetController(
            document: document, act: act, choices: choices,
            opening: GraphicFileSheetController.opening(for: act, selected: selected, in: choices))
        presentAsSheet(sheet)
    }

    /// The menu arm for the three; nil for any other action.
    func validateGraphicFileAction(_ action: Selector) -> Bool? {
        let act: GraphicFileAct
        switch action {
        case #selector(renameGraphic(_:)): act = .rename
        case #selector(deleteGraphic(_:)): act = .delete
        case #selector(restoreGraphicVersion(_:)): act = .restore
        default: return nil
        }
        guard let document = document else { return false }
        return GraphicFileSheetController.isOffered(act, in: document)
    }
}
// app/Sources/EditorViewController+Graphics.swift — the preview's answer to
// a module, font or asset changing on disk (road map 10 G3b; G-13, preview
// follows the newest revision). The plan does not change when a module
// does, so the §7.6 rebuild rule would skip it; the registry has already
// swapped the compiled set in, and a paused frame is recomposed by the
// one-tick round trip. A playing preview picks the new set up on its next
// frame by itself.

import AppKit

extension EditorViewController {
    @objc func graphicsDidChange(_ note: Notification) {
        guard let document = document, note.object as? ProjectDocument === document else { return }
        playback.refreshPausedFrame()
        inspector?.refresh(isLive: false)
    }
}

// app/Sources/GraphicCatalog.swift — what Insert ▸ Graphic… lists (spec §11
// G-45): the bundled templates and the project's own modules as categories
// of graphics, in the one order the sheet (`GraphicBrowserSheetController`)
// and `list_graphics` (`AgentServer+GraphicBrowser.swift`) both show.
//
// **A template is compiled to read its `meta`, once per process**
// (`GraphicTemplateLibrary`, G-45 (e)): its title is `meta.name`, its
// category `meta.category`, its description `meta.description`. The first
// read is on main, when the browser or the tool first asks; it compiles
// against a library of the bundled fonts alone and is memoised under a lock.
// The menu bar never reads it (chrome probes instantiate `AppDelegate()`).
//
// **A project module is read from the registry**: the document's compiled
// set, as the inspector and the op tools read it. A module that does not
// compile is still listed (`ok` false), titled from its stem, so a person
// can see it is there and read why it will not insert.

import Foundation

/// One graphic the browser lists.
struct GraphicBrowserItem: Equatable {
    enum Origin: String { case template, project }
    /// A template's file stem; a project module's name.
    let name: String
    /// `GraphicCatalog.title(meta:name:)`; a This Project duplicate carries
    /// " — <name>" (G-45 (e)).
    let title: String
    let description: String?
    /// The module's own category (`meta.category`, else "Other") — a This
    /// Project item keeps its own here though it is listed under This Project.
    let category: String
    let origin: Origin
    /// The module compiled.
    let ok: Bool
}

/// One category and its graphics, in order.
struct GraphicBrowserCategory: Equatable {
    let name: String
    let items: [GraphicBrowserItem]
}

enum GraphicCatalog {
    static let thisProject = "This Project", other = "Other"

    /// G-45 (a): `meta.category` trimmed when it is a non-empty string, else
    /// "Other".
    static func category(meta: [String: Any]) -> String {
        let named = (meta["category"] as? String)?
            .trimmingCharacters(in: .whitespacesAndNewlines) ?? ""
        return named.isEmpty ? other : named
    }

    /// G-45 (e): `meta.name` when it is a non-empty string, else the stem's
    /// title (`GraphicTemplates.title(for:)`).
    static func title(meta: [String: Any], name: String) -> String {
        let named = (meta["name"] as? String)?
            .trimmingCharacters(in: .whitespacesAndNewlines) ?? ""
        return named.isEmpty ? GraphicTemplates.title(for: name) : named
    }

    /// `meta.description` trimmed, nil when absent or blank.
    static func description(meta: [String: Any]) -> String? {
        let text = (meta["description"] as? String)?
            .trimmingCharacters(in: .whitespacesAndNewlines) ?? ""
        return text.isEmpty ? nil : text
    }

    /// One item from a compiled (or failed, or absent) registry entry.
    static func item(
        name: String, entry: GraphicRegistry.Entry?, origin: GraphicBrowserItem.Origin
    ) -> GraphicBrowserItem {
        var meta: [String: Any] = [:]
        var ok = false
        if case .compiled(_, _, let described, _)? = entry {
            meta = described
            ok = true
        }
        return GraphicBrowserItem(
            name: name, title: title(meta: meta, name: name), description: description(meta: meta),
            category: category(meta: meta), origin: origin, ok: ok)
    }

    /// G-45 (d): This Project first, only when `project` holds an item, with
    /// (e)'s duplicate titles told apart; then the templates' categories by
    /// case-insensitive name, Other last. Items by title case-insensitively,
    /// then by name.
    static func categories(
        templates: [GraphicBrowserItem], project: [GraphicBrowserItem]
    ) -> [GraphicBrowserCategory] {
        let ours: [GraphicBrowserCategory] = project.isEmpty ? []
            : [GraphicBrowserCategory(name: thisProject, items: sorted(distinguished(project)))]
        let names = Set(templates.map(\.category)).sorted { a, b in
            if (a == other) != (b == other) { return b == other }
            return a.caseInsensitiveCompare(b) == .orderedAscending
        }
        let theirs = names.map { name in
            GraphicBrowserCategory(
                name: name, items: sorted(templates.filter { $0.category == name }))
        }
        return ours + theirs
    }

    /// The document's list: the bundled templates and the modules its
    /// `graphics/` holds as the registry compiled them. Main.
    static func categories(for document: ProjectDocument) -> [GraphicBrowserCategory] {
        let templates = GraphicTemplateLibrary.shared.entries.map {
            item(name: $0.template.name, entry: $0.entry, origin: .template)
        }
        let modules = document.graphicStore?.scan.modules.keys.sorted() ?? []
        let project = modules.map {
            item(
                name: $0, entry: GraphicRegistry.shared.entry(named: $0, for: document.recipeKey),
                origin: .project)
        }
        return categories(templates: templates, project: project)
    }

    /// By title, case-insensitively, then by name.
    private static func sorted(_ items: [GraphicBrowserItem]) -> [GraphicBrowserItem] {
        items.sorted { a, b in
            switch a.title.caseInsensitiveCompare(b.title) {
            case .orderedAscending: return true
            case .orderedDescending: return false
            case .orderedSame: return a.name < b.name
            }
        }
    }

    /// Every item whose title another item shares, case-insensitively,
    /// titled "<title> — <name>".
    private static func distinguished(_ items: [GraphicBrowserItem]) -> [GraphicBrowserItem] {
        var counts: [String: Int] = [:]
        let key = { (title: String) in title.folding(options: .caseInsensitive, locale: nil) }
        for item in items { counts[key(item.title), default: 0] += 1 }
        return items.map { item in
            guard counts[key(item.title), default: 0] > 1 else { return item }
            return GraphicBrowserItem(
                name: item.name, title: "\(item.title) — \(item.name)",
                description: item.description, category: item.category, origin: item.origin,
                ok: item.ok)
        }
    }
}

/// The bundled templates, compiled once against a library of the bundled
/// fonts (G-45 (e)): what the browser reads their `meta` from and what its
/// preview draws them with.
final class GraphicTemplateLibrary {
    struct Entry {
        let template: GraphicTemplate
        let entry: GraphicRegistry.Entry
    }

    static let shared = GraphicTemplateLibrary(
        directory: GraphicTemplates.bundledDirectory, fonts: ProjectDocument.bundledFontsDirectory)

    private let directory: URL
    private let fonts: URL
    private let lock = NSLock()
    private var compiled: [Entry]?

    init(directory: URL, fonts: URL) {
        self.directory = directory
        self.fonts = fonts
    }

    /// Every template in `GraphicTemplates.list(in:)`'s order, compiled on
    /// the first read and kept. The first read is on main.
    var entries: [Entry] {
        lock.lock()
        defer { lock.unlock() }
        if let compiled = compiled { return compiled }
        let made = compile()
        compiled = made
        return made
    }

    func entry(named name: String) -> Entry? {
        entries.first { $0.template.name == name }
    }

    /// The bundled faces into a new library, then every template compiled
    /// against it. A face the engine refuses fails every template with its
    /// sentence, as `GraphicRegistry.install` does for a document.
    private func compile() -> [Entry] {
        let templates = GraphicTemplates.list(in: directory)
        let library = GraphicLibrary()
        var refused: [GraphicDiagnostic]?
        let faces = ((try? FileManager.default.contentsOfDirectory(
            at: fonts, includingPropertiesForKeys: nil)) ?? [])
            .filter { GraphicStore.fontExtensions.contains($0.pathExtension.lowercased()) }
            .sorted { $0.lastPathComponent < $1.lastPathComponent }
        do {
            for face in faces { try library.addFont(Data(contentsOf: face)) }
        } catch {
            refused = GraphicDiagnostic.of(error)
        }
        return templates.map { template in
            let bytes = (try? Data(contentsOf: template.url)) ?? Data()
            if let refused = refused {
                return Entry(template: template, entry: .failed(refused, revision: ""))
            }
            let file = GraphicModuleFile(
                name: template.name, url: template.url, bytes: bytes, revision: "")
            return Entry(template: template, entry: GraphicRegistry.compile(file, library: library))
        }
    }
}
